"use client";
import React, { useEffect, useState } from "react";
import { useRouter } from "next/navigation";
import axiosInstance from "@/utils/axiosIntance";
import {
  getTempCharacterData,
  clearTempCharacterData,
} from "@/app/create/actions/temp-character-data-action";
import { createCharacter } from "@/app/create/action";

interface ClassData {
  id: string;
  nome: string;
  description: string;
  imagem_url: string;
  // Adicione outras propriedades da sua classe se houver
}

export default function ClassSelection() {
  const router = useRouter();

  const [errorMessage, setErrorMessage] = useState("");
  const [loadingClasses, setLoadingClasses] = useState(true); // Nome corrigido para classes
  const [allClassesData, setAllClassesData] = useState<ClassData[]>([]); // Todas as classes da API
  const [visibleClasses, setVisibleClasses] = useState<ClassData[]>([]); // Classes que o usuário vê e pode escolher
  const [specialClasses, setSpecialClasses] = useState<ClassData[]>([]); // As 2 classes raras
  const [hasRolledSpecial, setHasRolledSpecial] = useState(false); // Indica se a rolagem especial ocorreu
  const [acceptedSpecialClasses, setAcceptedSpecialClasses] = useState(false); // Se o usuário aceitou as classes especiais
  const [selectedClassId, setSelectedClassId] = useState(""); // Nome corrigido para id (não classes)
  const [tempCharacterData, setTempCharacterData] = useState<any>(null); // Dados da raça, nome, gênero
  const [isLoading, setIsLoading] = useState(false); // Para o botão de criação

  useEffect(() => {
    async function loadDataAndClasses() {
      // 1. Carregar dados temporários do cookie
      const dataFromCookie = await getTempCharacterData();
      if (!dataFromCookie || !dataFromCookie.name || !dataFromCookie.id_race) {
        setErrorMessage(
          "Dados de personagem incompletos. Por favor, reinicie a criação."
        );
        router.replace("/create"); // Assumindo /create é sua primeira tela
        return;
      }
      setTempCharacterData(dataFromCookie);

      // 2. Carregar classes da API
      try {
        setLoadingClasses(true);
        const response = await axiosInstance.get("/classes");
        const rawResponseData = response.data.data;

        if (
          rawResponseData &&
          rawResponseData.classes &&
          Array.isArray(rawResponseData.classes)
        ) {
          const fetchedClasses: ClassData[] = rawResponseData.classes;
          setAllClassesData(fetchedClasses);

          // Exibe as duas primeiras classes por padrão
          if (fetchedClasses.length >= 2) {
            setVisibleClasses(fetchedClasses.slice(0, 2));
            setSelectedClassId(fetchedClasses[0].id); // Seleciona a primeira por padrão
          } else {
            setErrorMessage("Não há classes suficientes disponíveis.");
          }
        } else {
          console.error(
            "A API /classes não retornou um array de classes esperado:",
            rawResponseData
          );
          setErrorMessage("Formato de dados inesperado da API de classes.");
        }
      } catch (error) {
        console.error("Erro ao carregar as classes:", error);
        setErrorMessage(
          "Erro ao carregar as classes. Tente novamente mais tarde."
        );
      } finally {
        setLoadingClasses(false);
      }
    }
    loadDataAndClasses();
  }, [router]);

  const rollSpecialClasses = () => {
    // Evita múltiplas rolagens ou rolagens após aceitar/descartar
    if (hasRolledSpecial) return;

    // 1% de chance
    const roll = Math.random() * 100;
    console.log(`Rolagem para classes especiais: ${roll.toFixed(2)}%`);

    if (roll <= 1) {
      // 1% de chance
      // Seleciona duas classes aleatórias que não são as duas primeiras
      const nonDefaultClasses = allClassesData.slice(2);
      if (nonDefaultClasses.length >= 2) {
        // Shuffle the array to get random classes
        const shuffled = nonDefaultClasses.sort(() => 0.5 - Math.random());
        setSpecialClasses(shuffled.slice(0, 2));
        setHasRolledSpecial(true);
        setErrorMessage(
          "Parabéns! Você rolou classes especiais! Aceitar ou descartar?"
        );
      } else {
        setErrorMessage("Não há classes especiais suficientes para rolar.");
      }
    } else {
      setErrorMessage(
        "Sem sorte desta vez! Tente novamente (se o botão estiver disponível) ou confirme sua classe atual."
      );
    }
  };

  const acceptSpecialClasses = () => {
    setVisibleClasses(specialClasses); // Troca as classes visíveis pelas especiais
    setSelectedClassId(specialClasses[0].id); // Seleciona a primeira classe especial por padrão
    setAcceptedSpecialClasses(true);
    setHasRolledSpecial(true); // Garante que não possa rolar de novo
    setErrorMessage(""); // Limpa mensagem de sucesso da rolagem
  };

  const discardSpecialClasses = () => {
    setVisibleClasses(allClassesData.slice(0, 2)); // Volta para as classes padrão
    setSelectedClassId(allClassesData[0].id); // Volta a selecionar a primeira padrão
    setHasRolledSpecial(true); // Garante que não possa rolar de novo
    setErrorMessage(""); // Limpa mensagem
  };

  const currentClassDescription =
    (selectedClassId &&
      allClassesData.find((cls) => cls.id === selectedClassId)?.description) ||
    "Selecione uma classe para ver a descrição.";

  const handleCreateFinalCharacter = async (event: React.FormEvent) => {
    event.preventDefault();
    setErrorMessage("");

    if (
      !tempCharacterData ||
      !tempCharacterData.name ||
      !tempCharacterData.id_race
    ) {
      setErrorMessage(
        "Dados de personagem incompletos. Por favor, reinicie a criação."
      );
      router.replace("/create");
      return;
    }

    if (!selectedClassId) {
      // Corrigido para selectedClassId
      setErrorMessage("Por favor, selecione uma classe.");
      return;
    }

    setIsLoading(true); // Ativa o loading do botão

    const finalCharacterData = {
      name: tempCharacterData.name,
      gender: tempCharacterData.gender,
      id_race: tempCharacterData.id_race,
      id_class: selectedClassId, // Usando o id da classe selecionada
    };

    const result = await createCharacter(finalCharacterData);

    setIsLoading(false); // Desativa o loading do botão

    if (result.success) {
      alert("Personagem criado com sucesso!");
      router.replace("/dashboard");
    } else {
      setErrorMessage(
        result.message || "Erro desconhecido ao criar personagem."
      );
    }
  };

  // Renderização de loading e erro
  if (loadingClasses || !tempCharacterData) {
    return (
      <div
        className="flex items-center justify-center min-h-screen bg-cover bg-center"
        style={{ backgroundImage: "url('/images/homeMedieval.png')" }}
      >
        <div className="text-white text-3xl">Carregando classes...</div>
      </div>
    );
  }

  if (errorMessage && allClassesData.length === 0) {
    return (
      <div
        className="flex items-center justify-center min-h-screen bg-cover bg-center"
        style={{ backgroundImage: "url('/images/homeMedieval.png')" }}
      >
        <div className="text-red-500 text-3xl text-center">
          {errorMessage}
          <p className="text-xl mt-4">Por favor, recarregue a página.</p>
        </div>
      </div>
    );
  }

  if (!allClassesData || allClassesData.length === 0) {
    return (
      <div
        className="flex items-center justify-center min-h-screen bg-cover bg-center"
        style={{ backgroundImage: "url('/images/homeMedieval.png')" }}
      >
        <div className="text-white text-3xl">
          Nenhuma classe encontrada ou erro de carregamento.
        </div>
      </div>
    );
  }

  return (
    <div
      className="flex items-center justify-center min-h-screen bg-cover bg-center"
      style={{ backgroundImage: "url('/images/homeMedieval.png')" }}
    >
      <div className="bg-[#292018] p-8 rounded-lg shadow-xl w-[600px] border-[#F3B43F] border-4 font-imFeel text-white">
        <h2 className="text-4xl text-center text-[#F3B43F] mb-6">
          Escolha sua Classe
        </h2>

        {tempCharacterData && (
          <p className="text-center text-xl mb-4">
            Você escolheu: **{tempCharacterData.name}** (
            {tempCharacterData.gender}, {tempCharacterData.id_race})
          </p>
        )}

        <form onSubmit={handleCreateFinalCharacter}>
          <div className="flex justify-center gap-8 mb-6">
            {visibleClasses.map(
              (
                cls: ClassData // Renderiza apenas as classes visíveis
              ) => (
                <div
                  key={cls.id}
                  className={`relative p-4 rounded-lg cursor-pointer transition-all duration-200
                    ${
                      selectedClassId === cls.id // Corrigido para selectedClassId
                        ? "border-4 border-[#F3B43F] bg-[#3a2f24]"
                        : "border-4 border-transparent hover:border-[#F3B43F]/50"
                    }`}
                  onClick={() => setSelectedClassId(cls.id)} // Corrigido para setSelectedClassId
                >
                  <div
                    className="w-32 h-32 mx-auto mb-2 bg-gray-700 rounded-full overflow-hidden flex items-center justify-center"
                    style={{
                      backgroundImage: `url(${cls.imagem_url})`, // Assumindo 'imagem_url' em ClassData
                      backgroundSize: "cover",
                      backgroundPosition: "center",
                    }}
                  >
                    {!cls.imagem_url && (
                      <span className="text-white text-lg">{cls.nome}</span>
                    )}
                  </div>
                  <p className="text-center text-xl text-[#F3B43F]">
                    {cls.nome}
                  </p>
                </div>
              )
            )}
          </div>

          <div className="bg-[#DFC492] border-2 border-[#F3B43F] p-4 rounded-md mb-6 h-32 flex items-center justify-center text-center">
            <p className="text-lg text-[#1f1813] leading-relaxed">
              {currentClassDescription}
            </p>
          </div>

          {errorMessage && (
            <p className="text-red-500 text-center mb-4 text-xl">
              {errorMessage}
            </p>
          )}

          {/* Botão de Tentar Sorte */}
          {!hasRolledSpecial &&
            allClassesData.length > 2 && ( // Só mostra se houver classes para rolar
              <div className="flex justify-center mb-4">
                <button
                  type="button" // Important: it's not a submit button for the form
                  onClick={rollSpecialClasses}
                  className="w-[258px] h-[51px] bg-purple-700 font-imFeel text-white text-2xl hover:bg-purple-800 rounded-2xl cursor-pointer border-purple-900 border-4 transition-all duration-200"
                >
                  TENTAR A SORTE (1% de chance)
                </button>
              </div>
            )}

          {/* Opções para classes especiais roladas */}
          {hasRolledSpecial && specialClasses.length > 0 && (
            <div className="flex justify-center gap-4 mb-4">
              <button
                type="button"
                onClick={acceptSpecialClasses}
                className="w-[180px] h-[51px] bg-green-700 font-imFeel text-white text-xl hover:bg-green-800 rounded-2xl cursor-pointer border-green-900 border-4 transition-all duration-200"
              >
                ACEITAR NOVAS
              </button>
              <button
                type="button"
                onClick={discardSpecialClasses}
                className="w-[180px] h-[51px] bg-red-700 font-imFeel text-white text-xl hover:bg-red-800 rounded-2xl cursor-pointer border-red-900 border-4 transition-all duration-200"
              >
                DESCARTAR
              </button>
            </div>
          )}

          <div className="flex justify-center">
            <button
              type="submit"
              className="w-[258px] h-[51px] bg-[#8D6825] font-imFeel text-white text-4xl hover:bg-gradient-to-b rounded-2xl cursor-pointer hover:to-[#8D6825] hover:from-[#684424] border-[#F3B43F] border-4 transition-all duration-200"
              disabled={isLoading}
            >
              {isLoading ? "CRIANDO PERSONAGEM..." : "CRIAR PERSONAGEM"}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}
